-- QAAGA multi-role operations foundation (applied to project xrdudvpmleknomqlcdbc)
-- Adds global roles, property-scoped staff, support queue, and platform service-fee ledger.
create table if not exists public.user_role_assignments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('customer','host','co_host','property_manager','support','verification','finance','super_admin')),is_active boolean not null default true,assigned_by uuid references auth.users(id) on delete set null,assigned_at timestamptz not null default now(),expires_at timestamptz,unique(user_id,role));
create index if not exists idx_user_role_assignments_user_active on public.user_role_assignments(user_id,is_active);
create index if not exists idx_user_role_assignments_role_active on public.user_role_assignments(role,is_active);
create or replace function public.qaaga_is_super_admin() returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select coalesce((auth.jwt()->'app_metadata'->>'role')='admin',false) or exists(select 1 from public.user_role_assignments ura where ura.user_id=auth.uid() and ura.role='super_admin' and ura.is_active and (ura.expires_at is null or ura.expires_at>now())); $$;
create or replace function public.qaaga_has_role(p_role text) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select public.qaaga_is_super_admin() or exists(select 1 from public.user_role_assignments ura where ura.user_id=auth.uid() and ura.role=p_role and ura.is_active and (ura.expires_at is null or ura.expires_at>now())); $$;
create table if not exists public.property_staff_assignments(id uuid primary key default gen_random_uuid(),property_id text not null references public.properties(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('co_host','property_manager')),permissions jsonb not null default '{}'::jsonb,is_active boolean not null default true,assigned_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(property_id,user_id));
create index if not exists idx_property_staff_user_active on public.property_staff_assignments(user_id,is_active);
create index if not exists idx_property_staff_property_active on public.property_staff_assignments(property_id,is_active);
create or replace function public.qaaga_can_manage_property(p_property_id text) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select public.qaaga_is_super_admin() or exists(select 1 from public.properties p where p.id=p_property_id and lower(p.host_email)=lower(coalesce(auth.jwt()->>'email',''))) or exists(select 1 from public.property_staff_assignments psa where psa.property_id=p_property_id and psa.user_id=auth.uid() and psa.is_active); $$;
create table if not exists public.support_tickets(id uuid primary key default gen_random_uuid(),requester_id uuid not null references auth.users(id) on delete cascade,requester_email text not null,booking_id text references public.bookings(id) on delete set null,subject text not null check(length(trim(subject)) between 4 and 180),description text not null check(length(trim(description)) between 10 and 10000),category text not null default 'general' check(category in ('booking','payment','property','account','safety','general')),priority text not null default 'normal' check(priority in ('low','normal','high','urgent')),status text not null default 'open' check(status in ('open','in_progress','waiting_customer','resolved','closed')),assigned_to uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create index if not exists idx_support_tickets_requester on public.support_tickets(requester_id,created_at desc);
create index if not exists idx_support_tickets_queue on public.support_tickets(status,priority,created_at desc);
create index if not exists idx_support_tickets_assignee on public.support_tickets(assigned_to,status);
create or replace function public.qaaga_can_access_ticket(p_ticket_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select public.qaaga_is_super_admin() or public.qaaga_has_role('support') or exists(select 1 from public.support_tickets st where st.id=p_ticket_id and (st.requester_id=auth.uid() or st.assigned_to=auth.uid())); $$;
create table if not exists public.support_ticket_messages(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.support_tickets(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,body text not null check(length(trim(body)) between 1 and 10000),internal_note boolean not null default false,created_at timestamptz not null default now());
create index if not exists idx_support_ticket_messages_ticket on public.support_ticket_messages(ticket_id,created_at);
create table if not exists public.service_fee_ledger(id uuid primary key default gen_random_uuid(),booking_id text not null references public.bookings(id) on delete restrict,entry_type text not null check(entry_type in ('booking_service_fee','refund','adjustment')),amount numeric(12,2) not null check(amount>=0),currency text not null default 'BDT',status text not null default 'pending' check(status in ('pending','paid','refunded','void')),payment_method text,external_reference text,notes text,created_by uuid references auth.users(id) on delete set null,paid_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_service_fee_ledger_booking on public.service_fee_ledger(booking_id,created_at desc);
create index if not exists idx_service_fee_ledger_status on public.service_fee_ledger(status,created_at desc);
alter table public.user_role_assignments enable row level security;alter table public.property_staff_assignments enable row level security;alter table public.support_tickets enable row level security;alter table public.support_ticket_messages enable row level security;alter table public.service_fee_ledger enable row level security;
drop policy if exists qaaga_role_assignment_read on public.user_role_assignments;create policy qaaga_role_assignment_read on public.user_role_assignments for select to authenticated using(user_id=auth.uid() or public.qaaga_is_super_admin());
drop policy if exists qaaga_role_assignment_admin_write on public.user_role_assignments;create policy qaaga_role_assignment_admin_write on public.user_role_assignments for all to authenticated using(public.qaaga_is_super_admin()) with check(public.qaaga_is_super_admin());
drop policy if exists qaaga_property_staff_read on public.property_staff_assignments;create policy qaaga_property_staff_read on public.property_staff_assignments for select to authenticated using(user_id=auth.uid() or public.qaaga_is_super_admin() or exists(select 1 from public.properties p where p.id=property_id and lower(p.host_email)=lower(coalesce(auth.jwt()->>'email',''))));
drop policy if exists qaaga_property_staff_manage on public.property_staff_assignments;create policy qaaga_property_staff_manage on public.property_staff_assignments for all to authenticated using(public.qaaga_is_super_admin() or exists(select 1 from public.properties p where p.id=property_id and lower(p.host_email)=lower(coalesce(auth.jwt()->>'email','')))) with check(public.qaaga_is_super_admin() or exists(select 1 from public.properties p where p.id=property_id and lower(p.host_email)=lower(coalesce(auth.jwt()->>'email',''))));
drop policy if exists qaaga_support_ticket_read on public.support_tickets;create policy qaaga_support_ticket_read on public.support_tickets for select to authenticated using(requester_id=auth.uid() or assigned_to=auth.uid() or public.qaaga_has_role('support') or public.qaaga_is_super_admin());
drop policy if exists qaaga_support_ticket_create on public.support_tickets;create policy qaaga_support_ticket_create on public.support_tickets for insert to authenticated with check(requester_id=auth.uid() and lower(requester_email)=lower(coalesce(auth.jwt()->>'email','')));
drop policy if exists qaaga_support_ticket_staff_update on public.support_tickets;create policy qaaga_support_ticket_staff_update on public.support_tickets for update to authenticated using(public.qaaga_has_role('support') or public.qaaga_is_super_admin()) with check(public.qaaga_has_role('support') or public.qaaga_is_super_admin());
drop policy if exists qaaga_support_messages_read on public.support_ticket_messages;create policy qaaga_support_messages_read on public.support_ticket_messages for select to authenticated using(public.qaaga_can_access_ticket(ticket_id) and (not internal_note or public.qaaga_has_role('support') or public.qaaga_is_super_admin()));
drop policy if exists qaaga_support_messages_create on public.support_ticket_messages;create policy qaaga_support_messages_create on public.support_ticket_messages for insert to authenticated with check(sender_id=auth.uid() and public.qaaga_can_access_ticket(ticket_id) and (not internal_note or public.qaaga_has_role('support') or public.qaaga_is_super_admin()));
drop policy if exists qaaga_service_fee_ledger_read on public.service_fee_ledger;create policy qaaga_service_fee_ledger_read on public.service_fee_ledger for select to authenticated using(public.qaaga_has_role('finance') or public.qaaga_is_super_admin() or exists(select 1 from public.bookings b where b.id=booking_id and lower(b.customer_email)=lower(coalesce(auth.jwt()->>'email',''))));
drop policy if exists qaaga_service_fee_ledger_finance_write on public.service_fee_ledger;create policy qaaga_service_fee_ledger_finance_write on public.service_fee_ledger for all to authenticated using(public.qaaga_has_role('finance') or public.qaaga_is_super_admin()) with check(public.qaaga_has_role('finance') or public.qaaga_is_super_admin());
grant execute on function public.qaaga_is_super_admin() to authenticated;grant execute on function public.qaaga_has_role(text) to authenticated;grant execute on function public.qaaga_can_manage_property(text) to authenticated;grant execute on function public.qaaga_can_access_ticket(uuid) to authenticated;
comment on table public.user_role_assignments is 'QAAGA staff roles; assignments restricted to verified super administrators.';
comment on table public.property_staff_assignments is 'Property-scoped co-host and property manager assignments.';
comment on table public.support_tickets is 'Customer and host support queue.';
comment on table public.service_fee_ledger is 'QAAGA platform service-fee ledger; host rent paid directly to hosts is not QAAGA revenue.';
